import React from 'react';
import { View, Text, StyleSheet } from 'react-native';

export default function {{component_name}}({ consumed = {{consumed}}, goal = {{goal_kcal}} }) {
  const remaining = Math.max(0, goal - consumed);
  const pct = Math.min(100, (consumed / goal) * 100);
  return (
    <View style={styles.card}>
      <Text style={styles.label}>Calories</Text>
      <Text style={styles.big}>{consumed} <Text style={styles.unit}>/ {goal} kcal</Text></Text>
      <View style={styles.bar}><View style={[styles.fill, { width: `${pct}%` }]} /></View>
      <Text style={styles.left}>{remaining} kcal remaining</Text>
    </View>
  );
}
const styles = StyleSheet.create({
  card: { backgroundColor: '#fff', borderRadius: 16, padding: 20, shadowOpacity: 0.1, shadowRadius: 8 },
  label: { fontSize: 12, color: '#888', textTransform: 'uppercase' },
  big: { fontSize: 32, fontWeight: '700', marginVertical: 6 },
  unit: { fontSize: 14, color: '#888', fontWeight: '400' },
  bar: { height: 8, backgroundColor: '#eee', borderRadius: 4, overflow: 'hidden', marginVertical: 8 },
  fill: { height: '100%', backgroundColor: '#ff8c42' },
  left: { fontSize: 13, color: '#444' }
});
